// Deliberately explicit: qualification is never regenerated by the build.
import {mkdirSync,readFileSync,writeFileSync} from 'node:fs'
import {createHash} from 'node:crypto'
import {execFileSync} from 'node:child_process'
mkdirSync('output',{recursive:true})
const tests=['tests/valueBinaryCodec.test.ts','tests/cadBinaryTransport.test.ts','tests/ownRustCad.test.ts','tests/openscadParser.test.ts','tests/manifoldPlanBackend.test.ts','tests/cadGeometryKernel.test.ts','tests/languageConformance.test.ts','tests/geometryWorkerRealBoundary.test.ts','tests/mcpDirectGeometrySupervisor.test.ts','tests/mcpServer.test.ts']
const hash=path=>createHash('sha256').update(readFileSync(path)).digest('hex')
const wasmPath='src/generated/geometry-kernels/kernel_bg.wasm'
const wasmSha256=hash(wasmPath)
execFileSync(process.execPath,['node_modules/vitest/vitest.mjs','run',...tests,'--reporter=json','--outputFile=output/own-cad-qualification.json'],{stdio:'inherit'})
if(hash(wasmPath)!==wasmSha256)throw new Error('WASM changed during qualification')
const result=JSON.parse(readFileSync('output/own-cad-qualification.json','utf8'))
if(!result.success||result.numFailedTests||result.numPendingTests)throw new Error('Incomplete qualification')
const evidence={wasmSha256,noticesSha256:hash('THIRD_PARTY_NOTICES.md'),lockfileSha256:hash('package-lock.json'),rustLockfileSha256:hash('crates/Cargo.lock')}
writeFileSync('src/core/ownRustCadEvidence.ts',`// Exact artifact checked by the own Rust CAD qualification corpus.\nexport const OWN_RUST_CAD_EVIDENCE = Object.freeze(${JSON.stringify(evidence,null,2)})\n`)
writeFileSync('docs/qualification/own-rust-cad-v1.json',JSON.stringify({id:'own-rust-cad-v1',...evidence,tests,passedTests:result.numPassedTests,environment:{platform:process.platform,architecture:process.arch,node:process.version},scope:'Own CAD geometry and legacy frontend parity on one kernel, including Node worker boundaries. Not binary compatibility with archived Manifold meshes or browser/MCP parity qualification.',limitations:['Floating-point geometry, bounded CSG work and output','Source provenance across boolean operands is not qualified','TypeScript still hosts the legacy OpenSCAD evaluator and UI']},null,2)+'\n')
